#include <string>
#include <unordered_map>

class Solution {
public:
    int maxSubstrings(std::string word) {
        int ans = 0;
        std::unordered_map<char, int> first_seen;

        for (int i = 0; i < (int)word.length(); ++i) {
            char c = word[i];
            if (!first_seen.count(c)) {
                first_seen[c] = i;
            } else if (i - first_seen[c] + 1 >= 4) {
                ans++;
                first_seen.clear();
            }
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxSubstrings(String word) {
        int ans = 0;
        Map<Character, Integer> firstSeen = new HashMap<>();

        for (int i = 0; i < word.length(); ++i) {
            char c = word.charAt(i);
            if (!firstSeen.containsKey(c)) {
                firstSeen.put(c, i);
            } else if (i - firstSeen.get(c) + 1 >= 4) {
                ans++;
                firstSeen.clear();
            }
        }

        return ans;
    }
}

