var maxSubstrings = function(word) {
    let ans = 0;
    const firstSeen = new Map();

    for (let i = 0; i < word.length; ++i) {
        const c = word[i];
        if (!firstSeen.has(c)) {
            firstSeen.set(c, i);
        } else if (i - firstSeen.get(c) + 1 >= 4) {
            ans++;
            firstSeen.clear();
        }
    }

    return ans;
};
